)
async def admin_update_instrument(
) -> InstrumentVersionResponse:
    """Toggle activation status of a specific instrument version (admin only)."""
    _ = current_user
    row = await update_instrument_status(session, instrument_id, data)
    if row is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail="Instrument not found",
        )
    return InstrumentVersionResponse.model_validate(row)
@router.delete(
    "/admin/instruments/{instrument_id}",
    status_code=status.HTTP_204_NO_CONTENT,
    response_class=Response,
)
async def admin_delete_instrument(
) -> Response:
    """Delete an inactive instrument version (admin only)."""
    _ = current_user
    delete_result = await delete_instrument_version(session, instrument_id)
    if delete_result == "not_found":
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail="Instrument not found",
        )
    if delete_result == "active":
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail="Active instrument versions cannot be deleted",
        )
    if delete_result == "in_use":
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail="Instrument versions referenced by audits cannot be deleted",
        )
    return Response(status_code=status.HTTP_204_NO_CONTENT)

